# Issue #88 (proxy support): PROXY_ENV_VAR is an environment-variable
# *name* holding a comma-separated list of proxy URLs — never a literal
# proxy address baked into the script, same as FillStep credentials. If
# more than one is present, requests (or browser launches) rotate through
# them round-robin. A missing (not just empty) env var doesn't abort the
# run — it's treated as "no proxy configured", with a warning printed and
# the run flagged via EXIT_MISSING_ENV_VAR at the very end, once the script
# has otherwise completed successfully.
PROXY_ENV_VAR = 'PROXY_LIST'
_PROXY_ENV_VALUE = os.environ.get(PROXY_ENV_VAR)
_PROXY_ENV_MISSING = _PROXY_ENV_VALUE is None
if _PROXY_ENV_MISSING:
    print(f"Warning: environment variable '{PROXY_ENV_VAR}' is not set — connecting without a proxy.", file=sys.stderr)
_PROXY_LIST = [p.strip() for p in (_PROXY_ENV_VALUE or "").split(",") if p.strip()]
_proxy_cycle = itertools.cycle(_PROXY_LIST) if _PROXY_LIST else None


def _next_proxy():
    return next(_proxy_cycle) if _proxy_cycle else None


def _proxies_for_requests():
    proxy = _next_proxy()
    return {"http": proxy, "https": proxy} if proxy else None



# Issue #84: best-effort numeric normalization for a "toNumber" transform —
# finds the first numeric-looking substring and normalizes its decimal
# separator to '.', stripping thousands separators/currency symbols. When
# both '.' and ',' appear, the rightmost one is treated as the decimal point
# (handles both "1.234,56" and "1,234.56"); a single separator appearing more
# than once is treated as a thousands separator and stripped; a single
# separator appearing exactly once is treated as the decimal point (so
# "12,99"/"12.99" both work, at the cost of a genuinely ambiguous
# single-occurrence case like "1.234" always being read as 1.234, never as
# 1234 — chain a regex-extract transform first if that's not what's wanted).
# Empty string if nothing numeric is found.
def _to_number(value):
    match = re.search(r"-?\d[\d.,]*", value)
    if not match:
        return ""
    raw = match.group(0)
    last_dot = raw.rfind(".")
    last_comma = raw.rfind(",")
    if last_dot != -1 and last_comma != -1:
        decimal_pos = max(last_dot, last_comma)
        integer_part = raw[:decimal_pos].replace(".", "").replace(",", "")
        fractional_part = raw[decimal_pos + 1:]
        normalized = f"{integer_part}.{fractional_part}"
    elif raw.count(",") > 1 or raw.count(".") > 1:
        normalized = raw.replace(",", "").replace(".", "")
    else:
        normalized = raw.replace(",", ".")
    try:
        numeric = float(normalized)
    except ValueError:
        return ""
    return str(int(numeric)) if numeric.is_integer() else str(numeric)


# Issue #205: safe, explicit type-conversion transforms -- unlike toNumber's
# best-effort heuristic extraction, these either produce a well-formed value
# or fall back to their own clearly defined "onError" behavior
# ("KeepOriginal" leaves the pre-conversion value untouched, "UseDefault"
# substitutes the transform's own configured "defaultValue") rather than
# silently guessing.
_DATE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"(?P<yyyy>\d{4})", "mm": r"(?P<mm>\d{1,2})", "dd": r"(?P<dd>\d{1,2})"}


def _type_conversion_fallback(value, on_error, default_value):
    return default_value if on_error == "UseDefault" else value


def _to_integer(value, on_error, default_value):
    stripped = value.strip()
    if re.fullmatch(r"[+-]?\d+", stripped):
        return str(int(stripped))
    return _type_conversion_fallback(value, on_error, default_value)


def _to_boolean(value, on_error, default_value):
    normalized = value.strip().lower()
    if normalized in ("true", "1", "yes", "y"):
        return "True"
    if normalized in ("false", "0", "no", "n"):
        return "False"
    return _type_conversion_fallback(value, on_error, default_value)


# source_format is the same "{yyyy}"/"{mm}"/"{dd}" mini-template
# RangeSource.Format (RangeFormat.cs) already uses for ISO week/date
# parameters, compiled into a regex the same way (escape the literal
# template, then substitute each placeholder for its own capture group) so a
# format string valid on the companion side parses identically here. Also
# rejects a structurally-matching but non-existent calendar date (e.g.
# "2026-02-30") via date()'s own ValueError, not just a pattern match.
def _to_date(value, source_format, on_error, default_value):
    pattern = re.escape(source_format)
    for token, token_pattern in _DATE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), token_pattern)
    match = re.fullmatch(pattern, value.strip())
    if match:
        try:
            return date(int(match.group("yyyy")), int(match.group("mm")), int(match.group("dd"))).isoformat()
        except ValueError:
            pass
    return _type_conversion_fallback(value, on_error, default_value)


# Issue #234: strict price/currency conversion. number_format is one of
# ToCurrencyTransform.SupportedFormats, each written as its own example
# amount — its first punctuation mark is the thousands separator, its last
# the decimal separator (a space format also accepts no-break/narrow
# no-break spaces, the apostrophe format a typographic apostrophe). Finds
# the first number in the value (a separator only counts when a digit
# follows, so a trailing "." or "," after the amount is never swallowed),
# requires it to match the format strictly (thousands groups of exactly
# three digits, at most one decimal separator), and keeps the fraction
# digits exactly as scraped — no float rounding. Mirrored by
# toCurrencyPreview in extension/popup/field-transforms.js.
_CURRENCY_FORMATS = {
    "1.234,56": (",", "."),
    "1,234.56": (".", ","),
    "1 234,56": (",", "   "),
    "1'234.56": (".", "'’"),
}


def _to_currency(value, number_format, on_error, default_value):
    decimal_sep, thousands_seps = _CURRENCY_FORMATS.get(number_format, _CURRENCY_FORMATS["1.234,56"])
    candidate = re.search(r"[+-]?[0-9](?:[0-9]|[" + re.escape(decimal_sep + thousands_seps) + r"](?=[0-9]))*", value)
    if candidate:
        thousands = "[" + re.escape(thousands_seps) + "]"
        match = re.fullmatch(
            r"([+-]?)([0-9]{1,3}(?:" + thousands + r"[0-9]{3})+|[0-9]+)(?:" + re.escape(decimal_sep) + r"([0-9]+))?",
            candidate.group(0),
        )
        if match:
            integer = str(int(re.sub(thousands, "", match.group(2))))
            sign = "-" if match.group(1) == "-" else ""
            return sign + integer + ("." + match.group(3) if match.group(3) else "")
    return _type_conversion_fallback(value, on_error, default_value)


# Applies a field's ordered transform chain — each step's output feeds the
# next step's input, in the order the user configured them in.
# Issue #206: looks up another field's own already-computed value for
# CombineFieldsTransform/SplitFieldTransform. `siblings` is whatever
# representation the calling shape already has on hand at this point in
# extraction — a plain dict for flat/API-flat mode's in-progress row, or the
# in-construction parent ET.Element for container/API-tree mode (only that
# element's own direct children are considered, i.e. only siblings under the
# very same immediate parent group — see ScrapingPlanValidator's
# ValidateFieldTransformOrdering for why this is guaranteed to already be
# populated for a valid config). Missing/not-yet-computed simply resolves to
# "" rather than raising, the same "don't fail the whole row/element over
# one field" spirit every other transform here already follows.
def _resolve_transform_sibling(siblings, name):
    if siblings is None:
        return ""
    if isinstance(siblings, dict):
        return siblings.get(name, "")
    found = siblings.find(name)
    return (found.text or "") if found is not None else ""


def _apply_transforms(value, transforms, siblings=None):
    for t in transforms:
        kind = t["kind"]
        if kind == "trim":
            value = value.strip()
        elif kind == "regexExtract":
            match = re.search(t["pattern"], value)
            if match:
                try:
                    value = match.group(t.get("group", 0)) or ""
                except (IndexError, re.error):
                    value = ""
            else:
                value = ""
        elif kind == "replace":
            value = value.replace(t["find"], t["replacement"])
        elif kind == "toNumber":
            value = _to_number(value)
        elif kind == "toInteger":
            value = _to_integer(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toBoolean":
            value = _to_boolean(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toDate":
            value = _to_date(value, t.get("sourceFormat", "{yyyy}-{mm}-{dd}"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toCurrency":
            value = _to_currency(value, t.get("format", "1.234,56"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "combineFields":
            value = t.get("separator", " ").join(_resolve_transform_sibling(siblings, n) for n in t.get("sourceFieldNames", []))
        elif kind == "splitField":
            parts = _resolve_transform_sibling(siblings, t.get("sourceFieldName", "")).split(t.get("separator", " "))
            idx = t.get("index", 0)
            value = parts[idx] if 0 <= idx < len(parts) else ""
    return value


def _extract_flat_block(block, soup):
    selectors = block["selectors"]
    columns = {name: soup.select(sel) for name, sel in selectors.items()}
    n = max((len(v) for v in columns.values()), default=0)

    rows = []
    for i in range(n):
        row = {}
        for name, elements in columns.items():
            if i < len(elements):
                attr = block["attributes"].get(name)
                raw_value = elements[i].get(attr, "").strip() if attr else elements[i].get_text(strip=True)
                row[name] = _apply_transforms(raw_value, block["transforms"].get(name, []), row)
            else:
                row[name] = ""
        rows.append(row)
    return rows


# Same tree walk as scraper_grouped.py.j2's own extract_group() — only
# difference is required_field_names/block_name are threaded through
# explicitly instead of read off module-level constants, since a group
# block's own requiredFields check is per-block here.
def extract_group(scope, node, required_field_names, block_name, siblings=None):
    if "children" in node:
        if node["repeating"]:
            matches = scope.select(node["selector"])
        else:
            found = scope.select_one(node["selector"])
            matches = [found] if found else []

        elements = []
        for match in matches:
            el = ET.Element(node["name"])
            # Issue #206: el is this group instance's own in-construction
            # element — see scraper_grouped.py.j2's own identical doc
            # comment on this same pattern.
            for child in node["children"]:
                result = extract_group(match, child, required_field_names, block_name, el)
                if isinstance(result, list):
                    el.extend(result)
                else:
                    el.append(result)
            if node["repeating"] and required_field_names:
                dropped = False
                for name in required_field_names:
                    for req_match in el.iter(name):
                        if not (req_match.text or "").strip():
                            _REQUIRED_FIELDS_DROPPED[block_name] += 1
                            dropped = True
                            break
                    if dropped:
                        break
                if dropped:
                    continue
            elements.append(el)
        return elements

    el = ET.Element(node["name"])
    if node["mode"] == "exists":
        el.text = "true" if scope.select_one(node["selector"]) else "false"
    else:
        found = scope.select_one(node["selector"])
        if found is None:
            el.text = ""
        elif node["mode"] == "attribute":
            el.text = _apply_transforms(found.get(node["attribute"], "") or "", node["transform"], siblings)
        elif node["mode"] == "ownText":
            own_text = "".join(c for c in found.contents if isinstance(c, str)).strip()
            el.text = _apply_transforms(own_text, node["transform"], siblings)
        else:
            el.text = _apply_transforms(found.get_text(strip=True), node["transform"], siblings)
    return el






def scrape(url):
    # One entry per block: a list of rows (flat) or a list of ET.Element
    # (group) accumulated across every paginated page of this one URL — the
    # same per-URL accumulation scraper_grouped.py.j2's own scrape() already
    # does for a single shape, just once per block here.
    results = {block["name"]: [] for block in BLOCKS}
    page_number = 1
    page_url = url
    while page_url:
        _pace_request()
        response = _checked_request("Request", page_url, lambda: _send_with_retry(lambda _u=page_url: requests.get(_u, headers=HEADERS, proxies=_proxies_for_requests(), timeout=10), page_url))
        _require_ok("Request", page_url, response)
        soup = BeautifulSoup(response.content, "html.parser")

        any_new = False
        for block in BLOCKS:
            if block["shape"] == "flat":
                page_rows = _extract_flat_block(block, soup)
                if page_rows:
                    any_new = True
                results[block["name"]].extend(page_rows)
            else:
                required = next((c["fieldNames"] for c in block["hardening"]["checks"] if c["kind"] == "requiredFields"), [])
                page_elements = []
                for node in block["groups"]:
                    page_elements.extend(extract_group(soup, node, required, block["name"]))
                if page_elements:
                    any_new = True
                results[block["name"]].extend(page_elements)

        if not any_new:
            break

        if page_number >= PAGINATION_MAX_PAGES:
            break
        page_number += 1
        next_tag = soup.select_one(PAGINATION_NEXT_LINK_SELECTOR)
        next_href = next_tag.get("href") if next_tag else None
        page_url = urljoin(page_url, next_href) if next_href else None
    return results


# Issue #291: the XML 1.0 spec only allows tab, LF, CR and characters from
# U+0020 on (minus the surrogate range and U+FFFE/U+FFFF) — a control character
# such as the BEL (U+0007) is illegal even as a character reference, so there
# is no way to write it. Python's xml.etree.ElementTree does not check that and
# would serialize it raw, producing a file no conforming XML parser accepts
# (the companion's own trial-run check included). Such characters are removed
# from every element's text right before the tree is written as XML; JSON and
# CSV output don't need this (json.dump escapes them, CSV has no restriction).
_ILLEGAL_XML_CHARS_RE = re.compile("[\x00-\x08\x0b\x0c\x0e-\x1f\ud800-\udfff￾￿]")


def _strip_illegal_xml_chars(root):
    for element in root.iter():
        if element.text:
            element.text = _ILLEGAL_XML_CHARS_RE.sub("", element.text)
        if element.tail:
            element.tail = _ILLEGAL_XML_CHARS_RE.sub("", element.tail)
# Issue #319: a failed page request ends in one clean, actionable
# "ERROR: <what> to <url> failed: <detail>" line on stderr and a dedicated
# exit code instead of a raw requests/Playwright traceback — the same shape
# API mode has had since Issue #220 (PythonScriptVerifier.CleanScriptError
# turns such a line into /generate's error text). The hints say what to do
# about the status instead of only repeating it.
EXIT_REQUEST_FAILED = 7


def _request_failed(what, url, detail):
    print(f"ERROR: {what} to {url} failed: {detail}", file=sys.stderr)
    sys.exit(EXIT_REQUEST_FAILED)


def _http_error_detail(status_code):
    if status_code in (401, 403):
        reason = "Unauthorized" if status_code == 401 else "Forbidden"
        return (f"HTTP {status_code} ({reason}). The site refuses this script — it either requires a login "
                f"or blocks automated requests. If a login is needed, use the Browser engine with a login flow "
                f"or send a custom request header (e.g. Cookie or Authorization).")
    if status_code == 404:
        return "HTTP 404 (Not Found). The page doesn't exist (any more) — check the start URL."
    if status_code == 429:
        return ("HTTP 429 (Too Many Requests). The site is rate-limiting this script — enable "
                "\"Pause between requests\" or try again later.")
    if status_code >= 500:
        return (f"HTTP {status_code}. The site's server reported an error — this is usually temporary; "
                f"try again later or enable \"Retry on transient errors\".")
    return f"HTTP {status_code}."


# Runs one requests call; a connection error/timeout becomes a clean error.
# With "Retry on transient errors" enabled, `send` already contains the
# retries, so this only ever reports what is left once they are exhausted.
def _checked_request(what, url, send):
    try:
        return send()
    except requests.RequestException as e:
        _request_failed(what, url, f"could not reach the site ({e.__class__.__name__}).")


def _require_ok(what, url, response):
    if not response.ok:
        _request_failed(what, url, _http_error_detail(response.status_code))
# Issue #222: optional pause between outbound requests — a minimum gap
# between the starts of two consecutive requests, drawn uniformly from
# [REQUEST_DELAY_MIN_S, REQUEST_DELAY_MAX_S] each time. Only the part of the
# pause that hasn't already elapsed (e.g. while parsing the previous page) is
# actually slept, and the very first request of a run starts immediately.
# Each pause is announced on stdout — so a long run visibly isn't hanging,
# and so the companion's trial run can tell waiting apart from a stuck
# script (PythonScriptVerifier extends its own deadline by exactly the
# announced pause).
import random
import time

REQUEST_DELAY_MIN_S = 0.3
REQUEST_DELAY_MAX_S = 0.6
_last_request_started_at = None



def _pace_request():
    global _last_request_started_at
    if _last_request_started_at is not None:
        remaining = random.uniform(REQUEST_DELAY_MIN_S, REQUEST_DELAY_MAX_S) - (time.monotonic() - _last_request_started_at)
        if remaining > 0:
            print(f"Pausing {remaining:.2f} s before the next request (request delay)...", flush=True)
            time.sleep(remaining)
    _last_request_started_at = time.monotonic()


# Issue #223: optional retry with backoff on transient request failures — a
# connection error/timeout, or one of RETRY_ON_STATUS_CODES. Between attempts
# the script waits RETRY_DELAY_S (doubled after every retry when
# RETRY_EXPONENTIAL), or exactly what a 429/503's Retry-After header asks
# for; every wait is capped at RETRY_MAX_WAIT_S. Each retry is announced on
# stdout, so a scheduled run never degrades silently (and so the companion's
# trial run can tell the wait apart from a stuck script). Any other status
# (404/401/403, ...) is returned immediately, and once every attempt has
# failed, the last response is returned / the last error re-raised — exactly
# what the caller would have seen without retries.
import time

RETRY_MAX_ATTEMPTS = 2
RETRY_DELAY_S = 2.0
RETRY_EXPONENTIAL = True
RETRY_MAX_WAIT_S = 60.0
RETRY_ON_STATUS_CODES = {429, 502, 503, 504}


# Connection errors/timeouts of whichever HTTP stacks this script uses:
# requests' own, and Playwright's (navigations and page.context.request).
def _retryable_exceptions():
    found = []
    try:
        import requests as _requests
        found.append(_requests.RequestException)
    except ImportError:
        pass
    try:
        from playwright.sync_api import Error as _PlaywrightError
        found.append(_PlaywrightError)
    except ImportError:
        pass
    return tuple(found)


_RETRYABLE_EXCEPTIONS = _retryable_exceptions()


# Retry-After is either a number of seconds or an HTTP date; anything
# unparseable is ignored in favour of the configured delay.
def _retry_after_seconds(response):
    try:
        headers = {str(k).lower(): v for k, v in dict(getattr(response, "headers", None) or {}).items()}
    except (TypeError, ValueError):
        return None
    value = str(headers.get("retry-after") or "").strip()
    if not value:
        return None
    if value.isdigit():
        return float(value)
    try:
        from datetime import datetime, timezone
        from email.utils import parsedate_to_datetime
        return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
    except (TypeError, ValueError, IndexError):
        return None


def _send_with_retry(send, url):
    attempt = 1
    while True:
        try:
            response = send()
            # requests: status_code; Playwright: status (page.goto may also return None)
            status = getattr(response, "status_code", None)
            if status is None:
                status = getattr(response, "status", None)
            if status not in RETRY_ON_STATUS_CODES or attempt >= RETRY_MAX_ATTEMPTS:
                return response
            reason = f"HTTP {status}"
            retry_after = _retry_after_seconds(response) if status in (429, 503) else None
        except _RETRYABLE_EXCEPTIONS as e:
            if attempt >= RETRY_MAX_ATTEMPTS:
                raise
            reason = e.__class__.__name__
            retry_after = None
        wait = retry_after if retry_after is not None else RETRY_DELAY_S * (2 ** (attempt - 1) if RETRY_EXPONENTIAL else 1)
        wait = min(wait, RETRY_MAX_WAIT_S)
        attempt += 1
        print(f"Retrying in {wait:.1f} s (attempt {attempt} of {RETRY_MAX_ATTEMPTS}) after {reason}: {url}", flush=True)
        time.sleep(wait)
        _pace_request()


def main():

    per_block_data = {block["name"]: [] for block in BLOCKS if block["shape"] == "flat"}
    per_block_roots = {block["name"]: ET.Element("Ergebnis") for block in BLOCKS if block["shape"] == "group"}
    for url in URLS:
        page_results = scrape(url)
        for block in BLOCKS:
            if block["shape"] == "flat":
                per_block_data[block["name"]].extend(page_results[block["name"]])
            else:
                for el in page_results[block["name"]]:
                    per_block_roots[block["name"]].append(el)

    hardening_failed = False
    for block in BLOCKS:
        name = block["name"]
        if block["shape"] == "flat":
            data = per_block_data[name]
            if block["output_is_json"]:
                with open(block["output_path"], "w", encoding="utf-8") as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)
            else:
                with open(block["output_path"], "w", newline="", encoding="utf-8") as f:
                    writer = csv.DictWriter(f, fieldnames=block["field_order"])
                    writer.writeheader()
                    writer.writerows(data)
            count = len(data)
            print(f"Done — [{name}] {count} rows written to {block['output_path']}")
        else:
            root = per_block_roots[name]
            if block["output_is_json"]:
                with open(block["output_path"], "w", encoding="utf-8") as f:
                    json.dump(_xml_to_dict(root), f, ensure_ascii=False, indent=2)
            else:
                tree = ET.ElementTree(root)
                _strip_illegal_xml_chars(tree.getroot())
                ET.indent(tree)
                tree.write(block["output_path"], encoding="utf-8", xml_declaration=True)
            count = len(root.findall(".//*"))
            print(f"Done — [{name}] {count} elements written to {block['output_path']}")



    if _PROXY_ENV_MISSING:
        sys.exit(EXIT_MISSING_ENV_VAR)


if __name__ == "__main__":
    main()
